{"path": "/tmp/sv-1158c76805774d679740d89198662019/Components/Pages/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <div class="form-field">
        <label>Title</label>
        <input type="text" @bind="title" placeholder="Task title" />
    </div>
    <div class="form-field">
        <label>Assignee</label>
        <input type="text" @bind="assignee" placeholder="Assignee name" />
    </div>
    <div class="form-field">
        <label>Priority</label>
        <select @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-field">
        <label>Due Date</label>
        <input type="date" @bind="dueDate" />
    </div>
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save")
        </button>
        <button class="btn-cancel" @onclick="OnCancel" disabled="@isSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = "";
    [Parameter] public EventCallback<TaskItem> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        isSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(title, assignee, priority, dueDate);
            await OnSave.InvokeAsync(created);
        }
        finally
        {
            isSaving = false;
        }
    }
}
"}

{"path": "/tmp/sv-1158c76805774d679740d89198662019/Components/Pages/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="ColumnIndex > 0"
                      CanMoveRight="ColumnIndex < 2"
                      OnMoveLeft="() => MoveTask(task.Id, ColumnIndex - 1)"
                      OnMoveRight="() => MoveTask(task.Id, ColumnIndex + 1)" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm DefaultStatus="@ColumnName"
                     TaskService="TaskService"
                     OnSave="HandleTaskCreated"
                     OnCancel="() => showForm = false" />
    }
    else
    {
        <button class="btn-add" @onclick="() => showForm = true">+ Add Task</button>
    }
</div>

@code {
    private static readonly string[] Statuses = ["To Do", "In Progress", "Done"];

    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter] public int ColumnIndex { get; set; }
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private bool showForm;

    private async Task MoveTask(int taskId, int targetColumnIndex)
    {
        if (targetColumnIndex < 0 || targetColumnIndex > 2) return;
        await OnMoveTask.InvokeAsync((taskId, Statuses[targetColumnIndex]));
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        showForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }
}
"}

