toolArgs.file_text:
.loading {
    text-align: center;
    padding: 2rem;
    color: #666;
}

.error {
    background: #fee;
    border: 1px solid #c00;
    color: #c00;
    padding: 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
}

/* Stats Bar */
.board-stats {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat {
    background: #f0f4ff;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    text-align: center;
    min-width: 80px;
}

.stat-label {
    display: block;
    font-size: 0.75rem;
    color: #666;
    text-transform: uppercase;
}

.stat-value {
    display: block;
    font-size: 1.5rem;
    font-weight: bold;
    color: #333;
}

.stat-overdue .stat-value {
    color: #c00;
}

/* Search Bar */
.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
}

/* Board Columns */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.kanban-column {
    flex: 1;
    background: #f5f5f5;
    border-radius: 8px;
    padding: 0.75rem;
    min-width: 0;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.task-count {
    background: #ddd;
    border-radius: 999px;
    padding: 0.15rem 0.5rem;
    font-size: 0.8rem;
    font-weight: bold;
}

/* Task Card */
.task-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

.task-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem;
    font-size: 0.8rem;
    color: #666;
}

.priority-badge {
    display: inline-block;
    padding: 0.1rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: bold;
    color: #fff;
    margin-right: 0.5rem;
}

.priority-high {
    background: #dc3545;
}

.priority-medium {
    background: #ffc107;
    color: #333;
}

.priority-low {
    background: #28a745;
}

.task-due {
    font-size: 0.8rem;
    color: #555;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    background: none;
    border: 1px solid #ccc;
    border-radius: 4px;
    padding: 0.2rem 0.5rem;
    font-size: 0.75rem;
    cursor: pointer;
}

.btn-move:hover {
    background: #e8e8e8;
}

/* Add Task */
.btn-add {
    width: 100%;
    padding: 0.5rem;
    background: none;
    border: 1px dashed #aaa;
    border-radius: 6px;
    cursor: pointer;
    color: #666;
    font-size: 0.85rem;
}

.btn-add:hover {
    background: #e8e8e8;
}

/* Add Task Form */
.add-task-form {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 0.75rem;
}

.form-field {
    margin-bottom: 0.5rem;
}

.form-field label {
    display: block;
    font-size: 0.75rem;
    color: #666;
    margin-bottom: 0.15rem;
}

.form-field input,
.form-field select {
    width: 100%;
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.btn-save {
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save:hover {
    background: #0b5ed7;
}

.btn-cancel {
    background: none;
    border: 1px solid #ccc;
    border-radius: 4px;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-cancel:hover {
    background: #e8e8e8;
}

